import { useEffect, useState } from 'preact/hooks';
import { HB_ROMAN, MOVEMENT_TASKS, SCORING, isScoredTask, captureConditions, compareConditions, otherSide, type MovementTaskId } from '../../core';
import { FEATURES } from '../../config';
import { latestRating } from '../../data/export';
import { loadSnapshots } from '../../data/snapshots';
import { useApp } from '../../data/store';
import { changeSummary } from '../../rehab/findings';
import { buildPlan } from '../../rehab/planner';
import { AppBar, EstBadge, Notice, RegionMeters, Segmented } from '../components/common';
import { FindingsToExercises } from '../components/findings';
import { FaceWire } from '../components/FaceWire';
import { Icon } from '../icons';
import { FaceMapCard } from '../synk';
import { MuscleCard } from '../components/MuscleCard';
import { CONDITION_LABEL, SIDE_LABEL, TASK_LABEL, TASK_SHORT, WARNING_LABEL, dayLabel, fmtDateTime } from '../labels';

const MODE_LABEL = { video: '카메라', photo: '사진', demo: '데모' } as const;

/** Fixed decimals without a "-0.0" artefact. */
const fx = (x: number, d = 1): string => (Math.abs(x) < 0.5 * 10 ** -d ? 0 : x).toFixed(d);

export function SessionDetail({ id }: { id: string }) {
  const { sessions, integrity, ratings, profile, synk } = useApp();
  const idx = sessions.findIndex((s) => s.id === id);
  const s = sessions[idx];
  const [wireTask, setWireTask] = useState<MovementTaskId | 'rest'>('smile');
  const [view, setView] = useState<'mirror' | 'clinical'>(profile?.viewMode ?? 'mirror');
  // Optional photos of this assessment (settings → 평가 사진), as object URLs.
  const [photos, setPhotos] = useState<Partial<Record<string, string>> | null>(null);
  const [shape, setShape] = useState<'lines' | 'photo'>('lines');
  useEffect(() => {
    let urls: string[] = [];
    let live = true;
    loadSnapshots(id).then(
      (snap) => {
        if (!live || !snap) return;
        const map = Object.fromEntries(Object.entries(snap.items).flatMap(([k, v]) => (v ? [[k, URL.createObjectURL(v.blob)]] : [])));
        urls = Object.values(map);
        setPhotos(urls.length ? map : null);
      },
      () => setPhotos(null),
    );
    return () => {
      live = false;
      urls.forEach((u) => URL.revokeObjectURL(u));
    };
  }, [id]);
  // Synkinesis captured together in the full assessment.
  const linked = synk.find((x) => x.sessionId === id);
  if (!s) {
    return (
      <>
        <AppBar title="평가 결과" onBack />
        <main class="main">
          <div class="card">기록을 찾을 수 없습니다.</div>
        </main>
      </>
    );
  }
  const a = s.analysis;
  const sc = a.scores;
  const prev = sessions
    .slice(0, idx)
    .reverse()
    .find((x) => x.analysis.scores);
  const curCond = captureConditions(a);
  const prevCond = captureConditions(prev?.analysis);
  const condIssues = curCond && prevCond ? compareConditions(curCond, prevCond) : [];
  const aff = a.affectedSide;
  const healthy = otherSide(aff);
  const rating = latestRating(ratings, s.id);
  const kf = a.keyframes;
  const verified = integrity[s.id];
  const delta = (cur: number, before: number | undefined) => {
    if (before === undefined) return null;
    const d = cur - before;
    return (
      <span class={`chip ${d > 0 ? 'good' : d < 0 ? 'warn' : ''}`}>{`${d > 0 ? '▲' : d < 0 ? '▼' : '–'} ${Math.abs(d)} (이전 대비)`}</span>
    );
  };

  return (
    <>
      <AppBar title="평가 결과" sub={`${fmtDateTime(s.createdAt)} · ${dayLabel(s.daysSinceOnset)}`} onBack />
      <main class="main">
        <div class="row wrap">
          <span class="chip">{MODE_LABEL[s.mode]}</span>
          <span class="chip">마비 쪽: {SIDE_LABEL[aff]}</span>
          <span class={`chip ${verified ? 'good' : 'bad'}`}>
            <Icon name="shield" /> {verified ? '무결성 확인됨' : '무결성 오류'}
          </span>
        </div>

        {a.warnings.some((w) => w.code === 'SIDE_MISMATCH') && a.suggestedAffectedSide && (
          <div class="card danger">
            <Notice tone="danger">
              <b>
                이 기록은 설정된 마비 쪽({SIDE_LABEL[aff]})보다 {SIDE_LABEL[a.suggestedAffectedSide]}이 더 약하게 측정됐습니다.
              </b>
              <div class="small">마비 쪽 설정이 반대였다면 수치가 뒤집혀 있습니다(100% 이상). 설정을 확인하고 다시 평가해 주세요.</div>
            </Notice>
            <a class="btn block" href="#/assess">
              다시 평가하기
            </a>
          </div>
        )}

        {a.status !== 'complete' && (
          <div class="card warn">
            <Notice tone="warn">
              {a.status === 'failed' ? '측정에 실패한 기록입니다.' : '일부 동작이 측정되지 않아 종합 점수를 계산하지 않았습니다.'}
            </Notice>
          </div>
        )}

        {sc && prev && (
          <div class="card accent tight" aria-live="polite">
            <b class="small">{changeSummary(a, prev.analysis, s.daysSinceOnset - prev.daysSinceOnset)}</b>
            {condIssues.length > 0 && (
              <Notice tone="warn">
                <span class="small">
                  지난 평가와 촬영 조건이 달라 비교가 부정확할 수 있습니다. {condIssues.map((c) => CONDITION_LABEL[c]).join(' ')} 다음에는
                  같은 자리·거리·조명에서 평가하세요.
                </span>
              </Notice>
            )}
          </div>
        )}

        {sc && FEATURES.rehab === 'personalized' && (
          <div class="card">
            <div class="card-head">
              <h3>이 결과로 권하는 운동</h3>
              <a class="btn sm ghost" href="#/rehab">
                전체 계획 <Icon name="chev" />
              </a>
            </div>
            <FindingsToExercises analysis={a} plan={buildPlan({ daysSinceOnset: s.daysSinceOnset, latest: a })} />
          </div>
        )}

        {sc && (
          <div class="card">
            <div class="ink2 small">마비 쪽 움직임 (건강한 쪽 = 100%)</div>
            <div class="row between">
              <div>
                <span class="hero-num">{sc.functionIndex}</span>
                <span class="hero-unit">%</span>
              </div>
              {delta(sc.functionIndex, prev?.analysis.scores?.functionIndex)}
            </div>
            <RegionMeters regional={sc.regional} />
            {FEATURES.estimatedScales && (
              <div class="tiles">
                <div class="tile">
                  <span class="label">
                    Sunnybrook 종합 <EstBadge />
                  </span>
                  <span class="value">
                    {sc.composite}
                    <small>/100</small>
                  </span>
                </div>
                <div class="tile">
                  <span class="label">
                    House–Brackmann <EstBadge />
                  </span>
                  <span class="value">
                    {HB_ROMAN[sc.houseBrackmann.grade]}
                    <small>등급</small>
                  </span>
                </div>
              </div>
            )}
            {FEATURES.estimatedScales && (
              <p class="xsmall muted">
                안정 {sc.restScore} · 수의운동 {sc.voluntaryScore} · 동반운동 {sc.synkinesisScore} · 규칙 {sc.houseBrackmann.ruleId}. 추정
                등급은 임상적으로 검증되지 않았으며 의료진의 평가를 대신하지 않습니다.
              </p>
            )}
            {!sc.eyeClosureComplete && (
              <Notice tone="warn">
                <span class="small">눈이 완전히 감기지 않는 것으로 측정되었습니다. 눈 보호에 대해 주치의와 상의하세요.</span>
              </Notice>
            )}
          </div>
        )}

        {s.muscles && <MuscleCard m={s.muscles} />}

        {linked && linked.result.status !== 'failed' && (
          <>
            <FaceMapCard r={linked.result} analysis={s.analysis} />
            <a class="btn block" href={`#/synk/${linked.id}`}>
              연합운동 자세히 보기 (표정별 지도 · 도움 되는 운동) <Icon name="chev" />
            </a>
          </>
        )}

        {kf && (
          <div class="card">
            <div class="card-head">
              <h3>얼굴 움직임 모양</h3>
              <button class="btn sm ghost" onClick={() => setView(view === 'mirror' ? 'clinical' : 'mirror')}>
                <Icon name="mirror" /> {view === 'mirror' ? '거울 보기' : '임상 보기'}
              </button>
            </div>
            <div class="tabs-scroll" role="tablist">
              {(['rest', ...MOVEMENT_TASKS] as const).map((t) => (
                <button
                  class={`btn sm ${wireTask === t ? 'primary' : ''}`}
                  role="tab"
                  aria-selected={wireTask === t}
                  disabled={t !== 'rest' && !kf.tasks[t]}
                  onClick={() => setWireTask(t)}
                >
                  {TASK_SHORT[t]}
                </button>
              ))}
            </div>
            {photos && (
              <Segmented
                label="보기 방식"
                value={shape}
                onChange={setShape}
                options={[
                  { value: 'lines', label: '선 그림' },
                  { value: 'photo', label: '사진' },
                ]}
              />
            )}
            {photos && shape === 'photo' ? (
              photos[wireTask] ? (
                <img
                  src={photos[wireTask]}
                  alt={`${TASK_LABEL[wireTask]} 사진`}
                  style={{ display: 'block', width: '100%', borderRadius: '10px', marginTop: '8px', transform: view === 'mirror' ? 'scaleX(-1)' : undefined }}
                />
              ) : (
                <p class="small muted">이 동작은 사진이 없습니다.</p>
              )
            ) : (
              <FaceWire
                rest={kf.rest}
                expr={wireTask === 'rest' ? undefined : kf.tasks[wireTask]}
                view={view}
                affectedSide={aff}
                label={`${TASK_LABEL[wireTask]} 얼굴 윤곽`}
              />
            )}
            <p class="xsmall muted">
              {photos && shape === 'photo'
                ? '표정을 유지한 순간의 사진입니다. 이 폰에만 저장돼 있고, 설정 → 평가 사진에서 지울 수 있습니다.'
                : `회색: 안정 상태 · 파란색: 동작 시 · 주황 화살표: 주요 지점의 이동.${photos ? '' : ' 사진은 설정에서 켠 경우에만 이 폰에 저장됩니다.'}`}
            </p>
          </div>
        )}

        {Object.keys(a.tasks).length > 0 && (
          <div class="card">
            <h3>동작별 측정값</h3>
            <div class="table-scroll">
              <table class="data">
                <thead>
                  <tr>
                    <th>동작</th>
                    <th>대칭</th>
                    <th>건강한 쪽</th>
                    <th>마비 쪽</th>
                    <th>등급</th>
                    <th>동반</th>
                  </tr>
                </thead>
                <tbody>
                  {MOVEMENT_TASKS.map((t) => {
                    const m = a.tasks[t];
                    if (!m) return null;
                    const unit = m.excursionMm ? 'mm' : t === 'eyeClose' ? '%' : '';
                    const val = (side: 'left' | 'right') =>
                      m.excursionMm
                        ? fx(m.excursionMm[side])
                        : t === 'eyeClose'
                          ? Math.round(m.excursion[side] * 100)
                          : fx(m.excursion[side], 3);
                    return (
                      <tr>
                        <td>
                          {TASK_SHORT[t]}
                          {SCORING.lowConfidenceTasks.includes(t) && <span class="muted"> (참고)</span>}
                          {!m.reliable && ' ⚠'}
                        </td>
                        <td>{!isScoredTask(t) ? '제외' : m.reliable ? `${Math.round(Math.min(m.ratio, 2) * 100)}%` : '–'}</td>
                        <td>
                          {val(healthy)}
                          {unit}
                        </td>
                        <td>
                          {val(aff)}
                          {unit}
                        </td>
                        <td>{m.reliable && isScoredTask(t) ? `${m.grade}/5` : '–'}</td>
                        <td>{m.reliable ? `${m.synkinesisGrade}/3` : '–'}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            <p class="xsmall muted">
              대칭 = 마비 쪽 ÷ 건강한 쪽 움직임(⚠: 건강한 쪽 움직임 부족으로 비교 불가). mm는 홍채 지름(11.7mm) 기준 환산 근사치. 눈은 감긴
              정도(%). 등급·동반은 Sunnybrook 방식의 자동 추정치. 입술은 정확도 시험에서 측정이 확인되지 않아 대칭·점수에서 제외하고(동반운동만
              사용), 코는 오차가 커서 참고용입니다.
            </p>
          </div>
        )}

        {a.rest && (
          <div class="card tight">
            <h3>안정 시 대칭</h3>
            <div class="small ink2">
              눈 크기 비 {a.rest.eyeApertureRatio.toFixed(2)} · 입꼬리 높이 차 {fx(a.rest.mouthCornerDrop * (a.mmPerUnit ?? 62))}mm · 눈썹
              높이 차 {fx(a.rest.browDrop * (a.mmPerUnit ?? 62))}mm · 볼(중안면) 높이 차 {fx(a.rest.midfaceDrop * (a.mmPerUnit ?? 62))}mm
            </div>
            <div class="xsmall muted">+ 값은 마비 쪽이 더 낮음을 뜻합니다.</div>
          </div>
        )}

        {a.warnings.length > 0 && (
          <div class="card tight">
            {a.warnings.map((w) => (
              <Notice tone="warn">
                <span class="small">
                  {w.task && w.task !== 'rest' ? `[${TASK_SHORT[w.task]}] ` : ''}
                  {WARNING_LABEL[w.code]}
                </span>
              </Notice>
            ))}
          </div>
        )}

        {FEATURES.researchTools && (
          <div class="card tight">
            <div class="card-head">
              <h3>임상가 평가</h3>
              <a class="btn sm" href={`#/rate/${s.id}`}>
                <Icon name="clipboard" /> 입력
              </a>
            </div>
            {rating ? (
              <div class="small ink2">
                평가자 {rating.raterId} · HB {rating.houseBrackmann ? HB_ROMAN[rating.houseBrackmann] : '–'} · Sunnybrook{' '}
                {rating.sunnybrookComposite ?? '–'}
              </div>
            ) : (
              <div class="small muted">임상 검증 연구용: 의료진이 같은 방문의 등급을 입력하면 앱 추정치와 일치도를 계산합니다.</div>
            )}
          </div>
        )}

        <details class="card tight">
          <summary class="small ink2">측정 품질과 기술 정보</summary>
          <div class="table-scroll">
            <table class="data">
              <thead>
                <tr>
                  <th>단계</th>
                  <th>사용/유효/전체</th>
                  <th>좌우회전°</th>
                  <th>정렬오차</th>
                </tr>
              </thead>
              <tbody>
                {a.restQuality && (
                  <tr>
                    <td>안정</td>
                    <td>
                      {a.restQuality.framesUsed}/{a.restQuality.framesValid}/{a.restQuality.framesTotal}
                    </td>
                    <td>{a.restQuality.medianAbsYaw.toFixed(1)}</td>
                    <td>{Number.isFinite(a.restQuality.alignmentResidual) ? a.restQuality.alignmentResidual.toFixed(3) : '–'}</td>
                  </tr>
                )}
                {MOVEMENT_TASKS.map((t) => {
                  const m = a.tasks[t];
                  return m ? (
                    <tr>
                      <td>{TASK_SHORT[t]}</td>
                      <td>
                        {m.quality.framesUsed}/{m.quality.framesValid}/{m.quality.framesTotal}
                      </td>
                      <td>{m.quality.medianAbsYaw.toFixed(1)}</td>
                      <td>{m.quality.alignmentResidual.toFixed(3)}</td>
                    </tr>
                  ) : null;
                })}
              </tbody>
            </table>
          </div>
          <div class="xsmall ink2 stack" style={{ gap: '2px' }}>
            <div>
              알고리즘 {a.algorithm.id} v{a.algorithm.version} · 점수 {a.algorithm.scoringVersion} · 앱 v{s.app.version}
            </div>
            {s.engine ? (
              <div>
                {s.engine.runtime} · {s.engine.delegate} · 모델 {s.engine.modelIntegrity}
                <div class="mono">model sha256 {s.engine.modelSha256}</div>
              </div>
            ) : (
              <div>엔진: 합성 데이터(데모)</div>
            )}
            <div class="mono">record sha256 {s.integrity.hash}</div>
            <div>기록 ID {s.id}</div>
          </div>
        </details>
      </main>
    </>
  );
}
